# Writes src/Schema.jl from the plotly.js schema in the `plotly_artifacts` artifact (see Artifacts.toml).
# Run after updating the artifact:  julia deps/generate.jl
using Pkg
Pkg.activate(@__DIR__)
Pkg.instantiate()

using JSON

root = joinpath(@__DIR__, "..")
dir = Pkg.Artifacts.ensure_artifact_installed("plotly_artifacts", joinpath(root, "Artifacts.toml"))
version = strip(read(joinpath(dir, "version.txt"), String))
schema = JSON.parsefile(joinpath(dir, "plot-schema.json"))
valtypes = sort!(collect(keys(schema["defs"]["valObjects"])))
edittypes = sort!(unique(mapreduce(d -> vcat(d["flags"], d["extras"]), vcat, values(schema["defs"]["editType"]))))
sections = sort!(collect(keys(schema)))
# Enum values and sections share the module's namespace
allunique(vcat(valtypes, edittypes, sections)) || error("valTypes, editType flags, and schema sections share a name")

# Julia source for the JSON value `x`: objects become `D`s (keys sorted, one per line), `valType`s become `ValType`s,
# `editType`s become `EditType`s (a tuple if several flags), arrays of scalars stay on one line, and everything else is
# `repr`'d.  Lines after the first start with `indent`.
function write_value(io, x::AbstractDict, indent)
    isempty(x) && return print(io, "D()")
    println(io, "D(")
    foreach(sort!(collect(keys(x)))) do k
        print(io, indent, "    ", repr(Symbol(k)), " => ")
        if k == "valType"
            x[k] in valtypes || error("valType `$(x[k])` isn't in the schema's `defs.valObjects`")
            print(io, x[k])
        elseif k == "editType" && x[k] isa String  # (not `defs[:editType]`, which describes the flaglists)
            flags = split(x[k], "+")
            issubset(flags, edittypes) || error("editType `$(x[k])` isn't made of the schema's `defs.editType` flags")
            print(io, length(flags) == 1 ? only(flags) : "(" * join(flags, ", ") * ")")
        else
            write_value(io, x[k], indent * "    ")
        end
        println(io, ",")
    end
    print(io, indent, ")")
end

function write_value(io, x::AbstractVector, indent)
    # `Any[...]` unless every item has the same type, so Julia doesn't promote e.g. `[1, 2.5]` to `[1.0, 2.5]`
    print(io, !isempty(x) && allequal(map(typeof, x)) && !(x[1] isa Union{AbstractDict, AbstractVector}) ? "[" : "Any[")
    if all(v -> !(v isa Union{AbstractDict, AbstractVector}), x)
        join(io, map(repr, x), ", ")
    else
        println(io)
        foreach(x) do v
            print(io, indent, "    ")
            write_value(io, v, indent * "    ")
            println(io, ",")
        end
        print(io, indent)
    end
    print(io, "]")
end

write_value(io, x, indent) = print(io, repr(x))

open(joinpath(root, "src", "Schema.jl"), "w") do io
    println(io, "# Generated by deps/generate.jl from plotly.js $version's plot-schema.json.  Don't edit by hand.")
    println(io, "baremodule Schema")
    println(io)
    println(io, "using Base: @enum, Dict, =>")
    println(io)
    println(io, "const D = Dict{Symbol, Any}")
    println(io)
    println(io, "# Kinds of attribute value (each `:valType`), described in `defs[:valObjects]`")
    println(io, "@enum ValType ", join(valtypes, " "))
    println(io)
    println(io, "# Flags of each `:editType` (what plotly.js redraws when the attribute changes), described in `defs[:editType]`.")
    println(io, "# An attribute with several flags has a tuple of them, e.g. `(calc, arraydraw)`.")
    println(io, "@enum EditType ", join(edittypes, " "))
    println(io)
    println(io, "# The plot schema's sections: JSON objects as `D`s, arrays as `Vector`s, `null` as `nothing`")
    foreach(sections) do k
        print(io, "const ", k, " = ")
        write_value(io, schema[k], "")
        println(io)
        println(io)
    end
    println(io, "end  # module Schema")
end
